INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'How Tea Is Made', 'Tea is one of the most popular drinks in the world, and China is known for it. But do you know how tea is made? First, the tea leaves are picked by hand from the tea plants. This is usually done in spring, when the leaves are fresh and green. Then the leaves are dried in the sun or by machines. After that, they are processed carefully to bring out the flavor. Finally, the tea is packed and sent to shops all over the world. The whole process needs great care. Good tea is not made in a day. Next time you drink a cup of tea, remember the hard work behind it.', '说明文', 113, '[{"q": "How are the tea leaves picked?", "answer": "C", "options": ["By animals.", "By machines.", "By hand.", "In winter."], "explanation": "原文:picked by hand"}, {"q": "When are the leaves usually picked?", "answer": "D", "options": ["In winter.", "In autumn.", "In summer.", "In spring."], "explanation": "原文:done in spring"}, {"q": "What happens after the leaves are dried?", "answer": "D", "options": ["They are eaten.", "They are sold.", "They are thrown away.", "They are processed."], "explanation": "原文:processed carefully"}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["Why tea is cheap.", "Where to buy tea.", "How tea is made.", "Who drinks tea."], "explanation": "主旨:制茶过程"}, {"q": "What does the writer want us to remember?", "answer": "B", "options": ["The name of tea.", "The hard work behind tea.", "The color of tea.", "The price of tea."], "explanation": "原文:remember the hard work"}]'::jsonb, '[]'::jsonb, 3, '9', 'U5');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Art of Paper Cutting', 'Paper cutting is a traditional Chinese art with a long history. It is loved by many people around the world. In this art, beautiful pictures are cut from paper with scissors or a knife. The pictures are often about animals, flowers, or happy events. During the Spring Festival, paper cuttings are put on windows and doors. They are believed to bring good luck. Most paper cuttings are made by hand, and each one takes a lot of time and skill. Today, this old art is still taught in many schools, so that it will not be lost. Paper cutting shows the beauty of Chinese culture.', '说明文', 105, '[{"q": "What is paper cutting made with?", "answer": "D", "options": ["A machine.", "A pen.", "A brush.", "Scissors or a knife."], "explanation": "原文:cut with scissors or a knife"}, {"q": "Where are paper cuttings put during the Spring Festival?", "answer": "A", "options": ["On windows and doors.", "On the road.", "In books.", "On the floor."], "explanation": "原文:put on windows and doors"}, {"q": "Why are paper cuttings put up?", "answer": "A", "options": ["To bring good luck.", "To sell them.", "To clean rooms.", "To save money."], "explanation": "原文:bring good luck"}, {"q": "How are most paper cuttings made?", "answer": "B", "options": ["By computers.", "By hand.", "By printing.", "By machines."], "explanation": "原文:made by hand"}, {"q": "Why is paper cutting taught in schools?", "answer": "B", "options": ["To pass exams.", "So that it will not be lost.", "To make money.", "To buy paper."], "explanation": "原文:so it will not be lost"}]'::jsonb, '[]'::jsonb, 3, '9', 'U5');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Clay Figures of Tianjin', 'In the city of Tianjin, there is a famous traditional art called clay figures. These small figures are made of clay and are known for their lively colors and shapes. The art was started over a hundred years ago by a man named Zhang. First, soft clay is taken and shaped into people or animals by hand. Then the figures are dried and heated to make them hard. After that, they are painted in bright colors. Each figure takes several days to complete. Visitors to Tianjin often buy these figures as gifts. The clay figures are not just toys; they tell stories of Chinese life and history.', '记叙文', 107, '[{"q": "What are the Tianjin figures made of?", "answer": "B", "options": ["Wood.", "Clay.", "Steel.", "Glass."], "explanation": "原文:made of clay"}, {"q": "How is the clay first shaped?", "answer": "C", "options": ["By fire.", "By water.", "By hand.", "By machines."], "explanation": "原文:shaped by hand"}, {"q": "Why are the figures heated?", "answer": "B", "options": ["To sell them.", "To make them hard.", "To color them.", "To clean them."], "explanation": "原文:heated to make them hard"}, {"q": "What is done after the figures are dried and heated?", "answer": "C", "options": ["They are eaten.", "They are broken.", "They are painted.", "They are buried."], "explanation": "原文:painted in bright colors"}, {"q": "What do the clay figures tell?", "answer": "D", "options": ["Jokes.", "Songs.", "Prices.", "Stories of Chinese life and history."], "explanation": "原文:tell stories of Chinese life"}]'::jsonb, '[]'::jsonb, 3, '9', 'U5');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Made in Many Countries', 'Today, the things we use every day are made in many different countries. Your phone may be made in Korea, your watch in Switzerland, and your shoes in China. Why are products made all over the world? One reason is cost. Some countries can produce things at a lower price. Another reason is skill. Some places are known for special products, like cars from Germany. When you buy something, look at the label. It often tells you where the product was made. No matter where things are made, what matters most is good quality. A good product is welcomed everywhere in the world.', '议论文', 103, '[{"q": "Where might your watch be made?", "answer": "A", "options": ["In Switzerland.", "In Germany.", "In Korea.", "In China."], "explanation": "原文:watch in Switzerland"}, {"q": "What is one reason products are made worldwide?", "answer": "A", "options": ["Cost.", "Size.", "Color.", "Weather."], "explanation": "原文:One reason is cost"}, {"q": "What is Germany known for?", "answer": "D", "options": ["Shoes.", "Watches.", "Phones.", "Cars."], "explanation": "原文:cars from Germany"}, {"q": "Where can you find out where a product was made?", "answer": "C", "options": ["In the sky.", "On TV.", "On the label.", "In a song."], "explanation": "原文:look at the label"}, {"q": "What matters most according to the writer?", "answer": "B", "options": ["Bright color.", "Good quality.", "Big size.", "Low price."], "explanation": "原文:what matters most is good quality"}]'::jsonb, '[]'::jsonb, 3, '9', 'U5');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'A School Science Fair', 'Last week, an international science fair was held at our school. Students brought many amazing things that were made by themselves. Marcus made a model plane. It was made of used wood and glass, so it was good for the environment. When people asked how it was produced, he said every part was cut and joined by hand. Anna showed a small house that was built from old boxes. My project was a kite that was painted with lively colors. The teachers said our projects were creative because they were made from everyday materials. The science fair taught us that useful things can be made from things we already have.', '记叙文', 110, '[{"q": "When was the science fair held?", "answer": "A", "options": ["Last week.", "Last month.", "Yesterday.", "Last year."], "explanation": "原文:Last week"}, {"q": "What was Marcus''s model plane made of?", "answer": "D", "options": ["Cotton and silver.", "Paper and grass.", "Clay and steel.", "Used wood and glass."], "explanation": "原文:made of used wood and glass"}, {"q": "How was the model plane produced?", "answer": "C", "options": ["Printed by computer.", "Bought in a shop.", "Cut and joined by hand.", "Made by machines."], "explanation": "原文:cut and joined by hand"}, {"q": "What was Anna''s house built from?", "answer": "C", "options": ["New wood.", "Clay.", "Old boxes.", "Glass."], "explanation": "原文:built from old boxes"}, {"q": "Why did the teachers say the projects were creative?", "answer": "B", "options": ["Made of gold.", "Made from everyday materials.", "Bought online.", "Made by adults."], "explanation": "原文:made from everyday materials"}]'::jsonb, '[]'::jsonb, 3, '9', 'U5');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Buying Local Products', 'GREEN MARKET — SUPPORT LOCAL! Welcome to our Green Market! Here all the products are made by local people. FOOD: Fresh fruit and vegetables are grown on nearby farms. No long travel is needed, so they are always fresh. CRAFTS: Beautiful handbags and gloves are made by hand from local cotton. Each one is special. TOYS: Wooden toys are made from trees grown in our area. They are safe for children. WHY BUY LOCAL? Local products are fresh, and buying them helps people in our town. When you buy local, you also help protect the environment, because less traffic is needed to bring goods from far away. Come and support local products today!', '应用文', 113, '[{"q": "Where are the fruit and vegetables grown?", "answer": "C", "options": ["In other countries.", "In factories.", "On nearby farms.", "In the city center."], "explanation": "原文:grown on nearby farms"}, {"q": "What are the handbags made from?", "answer": "A", "options": ["Local cotton.", "Plastic.", "Steel.", "Paper."], "explanation": "原文:made from local cotton"}, {"q": "What are the wooden toys made from?", "answer": "D", "options": ["Old boxes.", "Glass.", "Metal.", "Trees grown in the area."], "explanation": "原文:from trees grown in our area"}, {"q": "Why are local fruits always fresh?", "answer": "B", "options": ["They are big.", "No long travel is needed.", "They are cheap.", "They are frozen."], "explanation": "原文:no long travel is needed"}, {"q": "How does buying local help the environment?", "answer": "D", "options": ["More factories open.", "More trees are cut.", "More paper is used.", "Less traffic is needed."], "explanation": "原文:less traffic is needed"}]'::jsonb, '[]'::jsonb, 3, '9', 'U5');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U5', 'How Silk Is Made', 'Silk is a beautiful material, and China is (1)____ for it. Have you ever wondered how silk is made? It is a long (2)____. First, silkworms are (3)____ on special farms. They eat the leaves of trees. After some weeks, each worm makes a small ball of silk thread. These balls are (4)____ collected by farmers. Then the thread is taken from them and (5)____ into long pieces. The thread is (6)____ cleaned and made ready. After that, it is (7)____ to make cloth. The cloth is often (8)____ in lovely colors. Finally, the silk is (9)____ and sent to shops. Real silk is not (10)____ in a day; it needs much time and care.', 115, 3, '[{"q": "1", "answer": "A", "options": ["known", "grown", "sold", "made"], "explanation": "be known for 以…闻名"}, {"q": "2", "answer": "D", "options": ["color", "price", "product", "process"], "explanation": "长过程 process"}, {"q": "3", "answer": "A", "options": ["kept", "eaten", "sold", "lost"], "explanation": "蚕被养 kept"}, {"q": "4", "answer": "B", "options": ["quickly", "carefully", "loudly", "sadly"], "explanation": "小心地收集 carefully"}, {"q": "5", "answer": "B", "options": ["taken", "made", "sold", "given"], "explanation": "被做成 made into"}, {"q": "6", "answer": "B", "options": ["once", "then", "seldom", "never"], "explanation": "然后 then"}, {"q": "7", "answer": "A", "options": ["used", "lost", "thrown", "broken"], "explanation": "被用来 used to"}, {"q": "8", "answer": "D", "options": ["written", "sung", "read", "painted"], "explanation": "染上颜色 painted"}, {"q": "9", "answer": "C", "options": ["opened", "cut", "packed", "dropped"], "explanation": "被包装 packed"}, {"q": "10", "answer": "C", "options": ["picked", "sold", "made", "grown"], "explanation": "非一日做成 made in a day"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U5', 'A Kite Festival', 'Every spring, a big kite festival is (1)____ in our city. People come from many (2)____ places to see it. The kites are (3)____ in many shapes and colors. Some look like birds, and others look like (4)____. Most of the kites are made (5)____ hand by local people. They are made (6)____ paper and thin bamboo. Making a good kite takes great (7)____. On the day of the festival, the sky is (8)____ with flying kites. Children are very (9)____ to fly their own kites. The festival is (10)____ by everyone, young and old. It is a wonderful part of our local culture.', 104, 3, '[{"q": "1", "answer": "C", "options": ["grown", "sold", "held", "made"], "explanation": "举办 held"}, {"q": "2", "answer": "D", "options": ["quiet", "empty", "same", "different"], "explanation": "不同地方 different"}, {"q": "3", "answer": "A", "options": ["made", "sold", "lost", "eaten"], "explanation": "被做成 made"}, {"q": "4", "answer": "B", "options": ["shoes", "fish", "books", "cars"], "explanation": "像鱼 fish"}, {"q": "5", "answer": "B", "options": ["of", "by", "in", "at"], "explanation": "made by hand 手工"}, {"q": "6", "answer": "B", "options": ["in", "of", "at", "by"], "explanation": "made of 看得出材料"}, {"q": "7", "answer": "A", "options": ["skill", "noise", "time", "money"], "explanation": "技巧 skill"}, {"q": "8", "answer": "D", "options": ["clean", "empty", "dark", "filled"], "explanation": "天空满是 filled with"}, {"q": "9", "answer": "C", "options": ["tired", "sad", "excited", "bored"], "explanation": "兴奋 excited"}, {"q": "10", "answer": "A", "options": ["loved", "hated", "sold", "lost"], "explanation": "被喜爱 loved"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U5', 'Recycled Art', 'At our school, an art show was (1)____ last week. The most special thing was that the art was (2)____ from waste materials. Students used things that are usually (3)____ away, like old boxes and bottles. One girl made a beautiful flower (4)____ old paper. A boy built a small car that was made (5)____ used metal. My friend and I made a robot. Its body was (6)____ of old cans. The teachers were (7)____ by our ideas. They said useful things can be (8)____ from waste. This show taught us to (9)____ throwing away useful things. When we use waste in a clever way, we also help (10)____ the environment.', 111, 3, '[{"q": "1", "answer": "B", "options": ["made", "held", "grown", "sold"], "explanation": "举办 held"}, {"q": "2", "answer": "C", "options": ["bought", "sold", "made", "grown"], "explanation": "被做成 made"}, {"q": "3", "answer": "D", "options": ["kept", "given", "sent", "thrown"], "explanation": "被扔掉 thrown away"}, {"q": "4", "answer": "B", "options": ["at", "from", "on", "by"], "explanation": "made from 看不出原貌"}, {"q": "5", "answer": "A", "options": ["of", "in", "by", "at"], "explanation": "made of 看得出"}, {"q": "6", "answer": "A", "options": ["made", "lost", "eaten", "sold"], "explanation": "被做成 made of"}, {"q": "7", "answer": "A", "options": ["surprised", "tired", "angry", "bored"], "explanation": "被惊到 surprised"}, {"q": "8", "answer": "C", "options": ["picked", "grown", "made", "sold"], "explanation": "被做成 made"}, {"q": "9", "answer": "D", "options": ["enjoy", "start", "forget", "avoid"], "explanation": "避免 avoid"}, {"q": "10", "answer": "B", "options": ["cut", "protect", "pollute", "waste"], "explanation": "保护 protect"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U5', 'The Story of Porcelain', 'Porcelain is one of the great products of China, and it is (1)____ all over the world. The making of porcelain is an old (2)____ that began long ago. First, a special kind of clay is (3)____ from the ground. Then it is shaped by (4)____ into bowls, cups, or plates. After that, the pieces are (5)____ in a very hot fire. This makes them hard and (6)____. Beautiful pictures are then (7)____ on the surface. Each piece is made with great (8)____. In the past, Chinese porcelain was (9)____ to many countries by ship. Today it is still (10)____ by people everywhere as a symbol of Chinese art.', 109, 3, '[{"q": "1", "answer": "C", "options": ["made", "lost", "known", "grown"], "explanation": "be known 知名"}, {"q": "2", "answer": "A", "options": ["art", "size", "price", "color"], "explanation": "古老技艺 art"}, {"q": "3", "answer": "B", "options": ["eaten", "taken", "thrown", "sold"], "explanation": "被取出 taken"}, {"q": "4", "answer": "D", "options": ["water", "fire", "machine", "hand"], "explanation": "by hand 手工"}, {"q": "5", "answer": "C", "options": ["cleaned", "broken", "heated", "cooled"], "explanation": "被加热 heated"}, {"q": "6", "answer": "A", "options": ["strong", "weak", "wet", "soft"], "explanation": "坚硬 strong"}, {"q": "7", "answer": "D", "options": ["sung", "written", "read", "painted"], "explanation": "被画上 painted"}, {"q": "8", "answer": "B", "options": ["noise", "care", "speed", "money"], "explanation": "用心 care"}, {"q": "9", "answer": "B", "options": ["lost", "sent", "kept", "eaten"], "explanation": "被运送 sent"}, {"q": "10", "answer": "A", "options": ["loved", "dropped", "hated", "sold"], "explanation": "被喜爱 loved"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U5', 'Cotton to Cloth', 'Have you ever thought about how your cotton clothes are (1)____? It is an interesting (2)____. First, cotton is (3)____ on large farms in warm areas. When it is ready, the cotton is (4)____ by hand or by machine. Then it is cleaned and made (5)____ thin thread. The thread is (6)____ into cloth in big factories. After that, the cloth is (7)____ in many bright colors. Workers then cut and (8)____ the cloth to make shirts and blouses. Finally, the clothes are (9)____ to shops in many countries. So your simple shirt is the (10)____ of much hard work and many steps.', 103, 3, '[{"q": "1", "answer": "B", "options": ["grown", "made", "sold", "lost"], "explanation": "被做成 made"}, {"q": "2", "answer": "C", "options": ["price", "game", "process", "color"], "explanation": "过程 process"}, {"q": "3", "answer": "D", "options": ["made", "sold", "eaten", "grown"], "explanation": "棉花被种 grown"}, {"q": "4", "answer": "D", "options": ["dropped", "thrown", "lost", "picked"], "explanation": "被采摘 picked"}, {"q": "5", "answer": "A", "options": ["into", "by", "of", "at"], "explanation": "made into 做成"}, {"q": "6", "answer": "A", "options": ["made", "grown", "kept", "sold"], "explanation": "被织成 made"}, {"q": "7", "answer": "B", "options": ["written", "painted", "read", "sung"], "explanation": "染色 painted/dyed"}, {"q": "8", "answer": "A", "options": ["join", "break", "lose", "throw"], "explanation": "缝合 join/sew"}, {"q": "9", "answer": "C", "options": ["lost", "kept", "sent", "eaten"], "explanation": "被送 sent"}, {"q": "10", "answer": "B", "options": ["size", "result", "price", "color"], "explanation": "结果 result"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U5', 'A Famous Local Brand', 'In our town, there is a famous (1)____ of tea that is loved by many people. No (2)____ where you go, you can see it in shops. How did it become so popular? The tea is (3)____ on the hills near our town. The leaves are (4)____ by hand in early spring. Then they are (5)____ with great care to keep the good taste. The tea is never (6)____ by machines, so its quality is high. Each box is (7)____ by local workers. Because the tea is so good, it is now (8)____ to other countries too. The local people are very (9)____ of their tea. They believe that good products are (10)____ with care, not with speed.', 118, 3, '[{"q": "1", "answer": "A", "options": ["brand", "game", "color", "price"], "explanation": "品牌 brand"}, {"q": "2", "answer": "B", "options": ["way", "matter", "problem", "time"], "explanation": "no matter 无论"}, {"q": "3", "answer": "D", "options": ["made", "eaten", "sold", "grown"], "explanation": "被种 grown"}, {"q": "4", "answer": "A", "options": ["picked", "dropped", "thrown", "lost"], "explanation": "被采 picked"}, {"q": "5", "answer": "A", "options": ["processed", "sold", "broken", "lost"], "explanation": "被加工 processed"}, {"q": "6", "answer": "C", "options": ["picked", "grown", "made", "sold"], "explanation": "不由机器做 made"}, {"q": "7", "answer": "D", "options": ["opened", "cut", "dropped", "packed"], "explanation": "被包装 packed"}, {"q": "8", "answer": "B", "options": ["eaten", "sold", "lost", "thrown"], "explanation": "被卖到 sold"}, {"q": "9", "answer": "C", "options": ["afraid", "bored", "proud", "tired"], "explanation": "自豪 proud of"}, {"q": "10", "answer": "B", "options": ["grown", "made", "sold", "lost"], "explanation": "用心做成 made with care"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U5 听力·对话 Asking About a Shirt', '九年级 Unit5 听力·被动语态/制作工艺', 2, 'W: What a nice shirt! Is it made of silk?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U5 听力·短文 How Tea Is Made', '九年级 Unit5 听力·被动语态/制作工艺', 2, 'Let me tell you how tea is made.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U5 听力·对话 At the Science Fair', '九年级 Unit5 听力·被动语态/制作工艺', 2, 'W: Wow, what a cool model plane! What is it made of?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U5 听力·短文 Paper Cutting', '九年级 Unit5 听力·被动语态/制作工艺', 2, 'Paper cutting is a traditional Chinese art.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U5 听力·对话 Buying a Handbag', '九年级 Unit5 听力·被动语态/制作工艺', 2, 'W: Excuse me, is this handbag made of leather?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U5 听力·短文 Clay Figures', '九年级 Unit5 听力·被动语态/制作工艺', 2, 'Clay figures are a famous art in Tianjin.
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'How a Product Is Made', '用被动语态介绍一种你熟悉的传统工艺品或产品(如风筝、剪纸、茶、瓷器等)是怎样制作的。写清原料、制作步骤、产地或特色。60词左右。', 'Write a short passage on the topic: "How a Product Is Made".', '["这个产品由什么材料制成(be made of/from)", "在哪里制造或出产(be made/produced in)", "制作的主要步骤(被动语态:is/are + 过去分词)", "它有什么特色或为什么受欢迎"]'::jsonb, 70, 100, 'Let me tell you how a kite is made. A Chinese kite is made of paper and thin bamboo. Most kites are made by hand by local people. First, the bamboo is cut and joined into a light frame. Then paper is put on the frame. After that, the kite is painted in bright and lively colors. Finally, a long string is added. Weifang is known for its beautiful kites. A good kite is made with great care, so it can fly high in the sky.', '内容完整:含材料/产地/步骤/特色四要点(4分)；被动语态:正确使用 is/are/was/were + 过去分词(3分)；语句通顺、衔接词得当 First/Then/Finally(2分)；词数达标、书写规范(1分)', 3, 'How a Product Is Made', '["be made of / from ...", "be made / produced in ...", "First, ... is/are ...", "Then it is ...", "Finally, it is ...", "be known for ...", "by hand", "with great care"]'::jsonb, '[]'::jsonb, '要点:这个产品由什么材料制成(be made of/from)；在哪里制造或出产(be made/produced in)；制作的主要步骤(被动语态:is/are + 过去分词)；它有什么特色或为什么受欢迎', '9', 'U5' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U5' AND topic='How a Product Is Made');
